"""Page-specific residential visuals and project qualification content."""
from urllib.parse import quote
CONCEPTS=[('villa-exterior','The contemporary villa','Clean lines. Deep shade. Room to breathe.','Contemporary villa','A contemporary two-storey villa concept with natural stone, timber screens and planted edges.'),('courtyard-home','The courtyard home','A quieter centre. A home open to light.','Courtyard home','A courtyard villa concept with a shaded verandah, central tree and warm natural materials.'),('large-residence','The grand family residence','Generous spaces. A distinctive arrival.','Large family residence','A spacious multi-level residence concept with terraces, warm stone and a double-height entrance.')]
LABEL='AI-generated design inspiration · Not a completed Leaf Infra project'
def photo(name,alt,cls='',eager=False):return f'<img class="{cls}" src="/assets/concepts/{name}.webp" alt="{alt}" width="1536" height="1024" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'
def caption():return f'<figcaption class="concept-disclosure">{LABEL}</figcaption>'
def studio():
 buttons=''.join(f'<button class="concept-tab" id="concept-tab-{i}" role="tab" aria-controls="concept-panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-concept-tab="{i}"><span>0{i+1}</span>{title}</button>' for i,(_,title,_,_,_) in enumerate(CONCEPTS))
 panels=''
 for i,(name,title,tag,preference,alt) in enumerate(CONCEPTS):
  panels+=f'<div class="concept-panel" id="concept-panel-{i}" role="tabpanel" aria-labelledby="concept-tab-{i}" {"hidden" if i else ""}><figure>{photo(name,alt)}{caption()}</figure><div class="concept-panel-copy"><span class="eyebrow">Residential inspiration / 0{i+1}</span><h3>{tag}</h3><p>Use this visual direction to start a discussion about your own site and priorities. Every home needs its own design, scope and estimate.</p><a class="btn" href="/contact?type={quote("Villa / independent home" if i<2 else "Large home / multi-level residence")}&concept={quote(preference)}">I’m drawn to this style <span>↗</span></a></div></div>'
 return f'<section class="section inspiration-section" id="home-inspiration"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Imagine the possibilities</span><h2>What does home<br>look like to you?</h2></div><p>Explore three visual directions. Choose what feels right, then tell us what matters in your own home.</p></div><div class="concept-tabs" role="tablist" aria-label="Explore home concepts">{buttons}</div>{panels}</div></section>'
def scope_section():return '''<section class="section scope-section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">What Leaf Infra does</span><h2>From the ground up.<br>Down to the details.</h2></div><p>Civil construction and coordinated execution. The exact services, materials and responsibilities are agreed for your project.</p></div><div class="scope-grid"><article><span class="scope-symbol">01 / GROUND</span><h3>Site & foundations</h3><p>Site preparation and foundation work against the structural design and agreed conditions.</p></article><article><span class="scope-symbol">02 / FRAME</span><h3>Structure & masonry</h3><p>RCC framing, walls, openings and the building envelope that shape your home.</p></article><article><span class="scope-symbol">03 / CONNECT</span><h3>Service coordination</h3><p>Plumbing and electrical interfaces, wet areas and specialist package boundaries.</p></article><article><span class="scope-symbol">04 / COMPLETE</span><h3>Finishes & completion</h3><p>Material specifications, finishing works and agreed handover checks.</p></article></div><a class="text-link" href="/services">Explore the full construction scope ↗</a></div></section>'''
def qualify():return '''<section class="section brief-band"><div class="wrap brief-grid"><div><span class="eyebrow">A useful first conversation</span><h2>You bring the vision.<br>Let’s understand the brief.</h2><p>Your site, scope and priorities help the team respond to your actual project, rather than a generic enquiry.</p><a class="btn white" href="/contact">Create your project brief ↗</a></div><ol class="brief-prompts"><li><span>01</span><div><b>Where will you build?</b><small>Site location, land status and access.</small></div></li><li><span>02</span><div><b>What are you planning?</b><small>Villa, duplex or larger family home.</small></div></li><li><span>03</span><div><b>What matters most?</b><small>Built-up area, budget range and start date.</small></div></li></ol></div></section>'''
def enrich(body,build,btn):
 # Each residential page has its own lead visual and interaction.
 original=body['index.html']
 trust=original[original.index('<section class="trust-strip">'):original.index('<section class="section">')]
 original_projects=original[original.index('<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Experience you can explore'):original.index('<section class="section soft"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Before you build')]
 body['index.html']='''<section class="visual-hero"><figure class="hero-residence">'''+photo('villa-exterior','AI-generated contemporary villa design concept with shaded balcony, garden and natural stone','',True)+'''</figure><div class="visual-hero-shade"></div><div class="wrap visual-hero-content"><div class="hero-overline"><span>Leaf Infra / Private residences</span><span>Chennai · Tamil Nadu</span></div><div class="hero-statement"><span class="eyebrow">Villas · Independent homes · Large residences</span><h1>A home like no other.<br><em>Built around you.</em></h1><p>Civil construction for your next chapter. Explore what’s possible for your villa or spacious family home, then build a clear plan with our team.</p><div class="actions"><a class="btn white" href="/contact">Let’s discuss your home ↗</a><a class="hero-explore" href="#home-inspiration">Explore home concepts ↓</a></div></div><div class="hero-image-note">AI-generated villa concept · Not a completed project</div></div></section>'''+trust+studio()+scope_section()+'''<section class="section living-section"><div class="wrap living-grid"><figure>'''+photo('courtyard-home','AI-generated villa courtyard with verandah, tree and warm natural materials')+caption()+'''</figure><div class="living-copy"><span class="eyebrow">A home, not just a building</span><h2>Light through the day.<br>Space through the years.</h2><p>Shaded balconies. A private courtyard. A generous living room for everyone to come together. The construction brief should begin with how you want to live.</p><div class="living-tags"><span>Independent villas</span><span>Courtyard homes</span><span>Duplex residences</span><span>Multi-level family homes</span></div><a class="text-link" href="/villas">Explore villa construction ↗</a></div></div></section>'''+qualify()+original_projects
 # Villas: courtyard-led photographic introduction; construction model appears here only.
 body['villas.html']=body['villas.html'].replace('</section>','</section>'+'''<section class="villa-feature"><div class="wrap villa-feature-grid"><figure>'''+photo('courtyard-home','AI-generated courtyard home concept with natural light, timber and a central tree','',True)+caption()+'''</figure><div class="feature-note"><span class="eyebrow">Design inspiration / Courtyard living</span><h2>Your own<br>quiet centre.</h2><p>A visual starting point for discussing daylight, privacy, ventilation and how your rooms connect. Your architect’s design and site conditions determine what is possible.</p><a class="text-link" href="/contact?type=Villa%20%2F%20independent%20home&concept=Courtyard%20home">Discuss a courtyard home ↗</a></div></div></section>''',1)
 # Large homes: remove the repeated construction model and introduce distinct image hotspots.
 start=body['large-homes.html'].index('<section class="section soft">')
 end=body['large-homes.html'].index('</section>',start)+len('</section>')
 hot='''<section class="section residence-explorer"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Explore a larger residence</span><h2>Big spaces.<br>Thoughtful connections.</h2></div><p>Select a detail to explore the questions behind a larger home. This is design inspiration, not an engineering specification.</p></div><div class="hotspot-layout"><figure class="hotspot-image">'''+photo('large-residence','AI-generated large residence concept with shaded terraces, stone facade and double-height entrance')+'''<button class="image-hotspot spot-entrance" data-detail="entrance" aria-label="Explore the entrance" aria-pressed="true">01</button><button class="image-hotspot spot-terrace" data-detail="terraces" aria-label="Explore terraces" aria-pressed="false">02</button><button class="image-hotspot spot-facade" data-detail="facade" aria-label="Explore materials" aria-pressed="false">03</button>'''+caption()+'''</figure><div class="detail-card" aria-live="polite"><span class="eyebrow" id="detail-number">01 / Arrival</span><h3 id="detail-title">An entrance with a purpose.</h3><p id="detail-description">Discuss how people arrive, where vehicles stop, and how the entrance connects to family living spaces. Double-height areas also affect structure, finishes and service coordination.</p><a class="text-link" href="/contact?type=Large%20home%20%2F%20multi-level%20residence&concept=Large%20family%20residence">Discuss a larger home ↗</a></div></div></div></section>'''
 body['large-homes.html']=body['large-homes.html'][:start]+hot+body['large-homes.html'][end:]
 # Put the large-residence image immediately below the page introduction.
 body['large-homes.html']=body['large-homes.html'].replace('</section>','</section><figure class="large-home-banner">'+photo('large-residence','AI-generated spacious three-level family residence with stone, terraces and warm lighting','',True)+caption()+'</figure>',1)
 body['services.html']=body['services.html'].replace('<section class="section">',scope_section()+'<section class="section">',1)
 # Optional qualification fields feed the existing validated enquiry backend.
 extras='''<fieldset class="brief-fields full"><legend>Your project brief <span>Optional · helps us prepare</span></legend><div class="brief-field-grid"><div class="field"><label for="d-land">Land status</label><select id="d-land" name="landStatus"><option value="">Select land status</option><option>I own the plot</option><option>Plot purchase in progress</option><option>Still looking for land</option><option>Existing property / redevelopment</option></select></div><div class="field"><label for="d-budget">Construction budget range</label><select id="d-budget" name="budget"><option value="">Select a range</option><option>Below ₹50 lakh</option><option>₹50 lakh–₹1 crore</option><option>₹1–₹2 crore</option><option>Above ₹2 crore</option><option>I need guidance</option></select></div><div class="field"><label for="d-timeline">When would you like to start?</label><select id="d-timeline" name="timeline"><option value="">Select a timeline</option><option>Within 3 months</option><option>3–6 months</option><option>6–12 months</option><option>Exploring for later</option></select></div><div class="field"><label for="d-preference">Visual preference</label><select id="d-preference" name="concept"><option value="">No preference yet</option><option>Contemporary villa</option><option>Courtyard home</option><option>Large family residence</option></select></div></div><p class="form-note">Your budget is a planning preference, not a quoted construction price.</p></fieldset>'''
 body['contact.html']=body['contact.html'].replace('<div class="field full"><label for="d-message">',extras+'<div class="field full"><label for="d-message">').replace('maxlength="3000"','maxlength="2400"')
 return body
